 auto Platform=Spawn(TEXT("temple_of_the_land"),0,{60,60});auto Candidate=Spawn(TEXT("man_of_moroni"),1,{65,60});const int CandidateId=Candidate->Id;W->Players[0].Upgrades.Add(TEXT("by_the_pride_of_their_hearts"));W->Religion(18);Check(TEXT("lamanites.rameumptom_converts_captain"),W->Find(CandidateId)->Owner==0&&W->D(*W->Find(CandidateId)).Id==TEXT("zoramite_captain"));
