 auto Lodge=Spawn(TEXT("secret_combination_lodge"),0,{60,60});W->Religion(1);Check(TEXT("gadianton.secret_lodge_undiscovered"),!Lodge->bDiscovered);Spawn(TEXT("wilderness_spy"),1,{64,60});W->Religion(1);Check(TEXT("gadianton.scouting_exposes_lodge"),Lodge->bDiscovered);
 Reset(TEXT("coriantumr"));auto Flock=Spawn(TEXT("gathering_of_flocks"),0,{40,40});auto Sheep=Spawn(TEXT("sheep"),0,{42,40});Sheep->HomeBuilding=Flock->Id;Enemy=Spawn(TEXT("cimeter_bearer"),1,{46,40});W->Kill(Flock->Id,Enemy->Id);const double Food=W->Players[1].Resources.X;W->EconomyAuras(1);Check(TEXT("sheep.captured_with_destroyed_flock"),Sheep->Owner==1&&Sheep->HomeBuilding==0&&W->Players[1].Resources.X>Food);
 Reset(TEXT("laban"));W->Players[0].Favor=100;auto Guard=Spawn(TEXT("one_of_the_fifty"),0,{40,40});auto Main=Spawn(TEXT("cimeter_bearer"),1,{41,40});auto Nearby=Spawn(TEXT("cimeter_bearer"),1,{42,40});Guard->Order=TEXT("attack");Guard->Target=Main->Id;Guard->bDirectAttack=true;const float HP=Nearby->HP;W->Combat(*Guard,.1f);Check(TEXT("laban.drunken_guard_splash"),Nearby->HP<HP);
 auto Report=MakeShared<FJsonObject>();Report->SetNumberField(TEXT("passed"),Passed);Report->SetNumberField(TEXT("failed"),Failed);Report->SetArrayField(TEXT("assertions"),Results);FString JSON;FJsonSerializer::Serialize(Report,TJsonWriterFactory<>::Create(&JSON));const FString Dir=FPaths::ProjectSavedDir()/TEXT("Tests");IFileManager::Get().MakeDirectory(*Dir,true);FFileHelper::SaveStringToFile(JSON,*(Dir/TEXT("religion-v03-tests.json")));C->Destroy();UE_LOG(LogTemp,Display,TEXT("RTS_RELIGION_TESTS passed=%d failed=%d"),Passed,Failed);return Failed==0;
